import {makeRace,position,settle} from './engine.js';
const $=id=>document.getElementById(id);const fmt=n=>n.toLocaleString('ja-JP');const key='amber-derby-v1';let saved={};try{saved=JSON.parse(localStorage.getItem(key)||'{}')||{}}catch{}
let credit=Number.isSafeInteger(saved.credit)&&saved.credit>=0?saved.credit:1000,round=Number.isSafeInteger(saved.round)&&saved.round>0?saved.round:1,played=Number.isSafeInteger(saved.played)&&saved.played>=0?saved.played:0,hits=Number.isSafeInteger(saved.hits)&&saved.hits>=0?saved.hits:0,history=Array.isArray(saved.history)?saved.history.filter(x=>x&&typeof x.winner==='string'&&Number.isFinite(x.payout)&&Number.isFinite(x.bet)&&Number.isFinite(x.round)).slice(0,5):[];
if(Number.isSafeInteger(saved.pending)&&saved.pending>0)credit+=saved.pending;
let field=makeRace(),selected=0,type='win',amount=10,tickets=[],state='betting',lastPay=0,sound=false,audio,elapsed=0,startAt=0,lastBeat=0,lastStage=-1;
function save(){try{localStorage.setItem(key,JSON.stringify({credit,round,played,hits,history,pending:state==='result'?0:total()}))}catch{}}
function say(s){$('commentary').textContent=s}
function tone(freq=440,duration=.1){if(!sound)return;try{audio ||= new (window.AudioContext||window.webkitAudioContext)();audio.resume();const osc=audio.createOscillator(),gain=audio.createGain();osc.type='square';osc.frequency.value=freq;gain.gain.setValueAtTime(.025,audio.currentTime);gain.gain.exponentialRampToValueAtTime(.001,audio.currentTime+duration);osc.connect(gain);gain.connect(audio.destination);osc.start();osc.stop(audio.currentTime+duration)}catch{}}
$('sound').onclick=()=>{sound=!sound;$('sound').textContent=sound?'♪ SOUND ON':'♪ SOUND OFF';$('sound').setAttribute('aria-pressed',sound);tone(660)};
function total(){return tickets.reduce((s,t)=>s+t.amount,0)}
function update(){
$('credit').textContent=fmt(credit);$('total').textContent=fmt(total());$('payout').textContent=fmt(lastPay);$('race-label').textContent=`RACE ${String(round).padStart(2,'0')}`;
$('horses').replaceChildren(...field.map(h=>{const b=document.createElement('button');b.className='horse-row'+(h.id===selected?' active':'');b.setAttribute('aria-pressed',h.id===selected);b.disabled=state!=='betting';b.innerHTML=`<span class="horse-info"><span class="number" style="--horse:${h.color}">${h.id+1}</span><span><strong>${h.name}</strong><small>${h.style} · 調子 ${['○ 平常','◎ 好調','△ 気まぐれ'][h.form]}</small></span></span><span>${h.win.toFixed(1)}</span><span>${h.place.toFixed(1)}</span>`;b.onclick=()=>{selected=h.id;update();tone(400)};return b}));
const h=field[selected];$('selected-name').textContent=h.name;$('selected-style').textContent=`${h.style} · ${type==='win'?'単勝':'複勝'} ${h[type].toFixed(1)}倍`;$('selected-number').textContent=selected+1;$('selected-number').style.setProperty('--horse',h.color);
for(const t of ['win','place']){$(t).setAttribute('aria-pressed',type===t);$(t).disabled=state!=='betting'}document.querySelectorAll('[data-amount]').forEach(b=>{b.setAttribute('aria-pressed',+b.dataset.amount===amount);b.disabled=state!=='betting'});
$('add-label').textContent=`${amount}枚 投票する`;$('add').disabled=state!=='betting'||credit<amount;$('clear').disabled=state!=='betting'||!tickets.length;$('start').disabled=state==='racing'||(state==='betting'&&!tickets.length);$('start').innerHTML=state==='result'?'次のレースへ <span>↻</span>':state==='racing'?'レース開催中…':'レーススタート <span>▶</span>';
$('tickets').replaceChildren();if(!tickets.length)$('tickets').textContent='投票券はまだありません';tickets.forEach(t=>{const d=document.createElement('div');d.className='ticket';d.innerHTML=`<span>${t.id+1} ${field[t.id].name} / ${t.type==='win'?'単勝':'複勝'}</span><b>${fmt(t.amount)}枚</b>`;$('tickets').append(d)});
$('refill').hidden=credit>=10||state==='racing'||tickets.length>0;$('stats').textContent=`${played}戦 · 的中 ${hits}回`;
$('history').replaceChildren();if(!history.length)$('history').textContent='最初のレースが、ここから始まります。';history.forEach(r=>{const d=document.createElement('div');d.className='history-row';const a=document.createElement('span');a.textContent=`R${String(r.round).padStart(2,'0')} · 1着 ${r.winner}`;const b=document.createElement('b');b.textContent=`${r.payout?'的中':'不的中'} / 払戻 ${fmt(r.payout)}枚`;d.append(a,b);$('history').append(d)});
}
for(const t of ['win','place'])$(t).onclick=()=>{if(state!=='betting')return;type=t;update();tone(450)};document.querySelectorAll('[data-amount]').forEach(b=>b.onclick=()=>{if(state!=='betting')return;amount=+b.dataset.amount;update();tone(480)});
$('add').onclick=()=>{if(state!=='betting'||credit<amount)return;credit-=amount;const t=tickets.find(t=>t.id===selected&&t.type===type);if(t)t.amount+=amount;else tickets.push({id:selected,type,amount});save();update();tone(700);say(`${field[selected].name}に${type==='win'?'単勝':'複勝'} ${amount}枚。投票を受け付けました。`)};
$('clear').onclick=()=>{if(state!=='betting')return;credit+=total();tickets=[];save();update();say('投票を取り消し、メダルを戻しました。')};
$('refill').onclick=()=>{if(credit>=10||state==='racing'||tickets.length)return;credit+=1000;save();update();say('練習メダルを1,000枚補充しました。')};
$('start').onclick=()=>{if(state==='racing')return;if(state==='result'){round++;field=makeRace();tickets=[];state='betting';elapsed=0;lastStage=-1;lastBeat=0;$('result').hidden=true;$('phase').textContent='BETTING OPEN';$('track-message').textContent='次の主役は、どの馬だ。';$('distance').textContent='START ━━━━━━━━━ FINISH';document.querySelector('.monitor').classList.remove('racing');say('新しい出走表です。馬の調子と倍率を見て投票しましょう。');save();update();draw(0);return}if(!tickets.length)return;state='racing';startAt=performance.now();document.querySelector('.monitor').classList.add('racing');$('phase').textContent='LIVE RACE';$('track-message').textContent='ゲートイン…';tone(523,.2);say('各馬、ゲートに入りました。まもなくスタート！');update();requestAnimationFrame(frame)};
function finish(){state='result';const {order,payout,hit}=settle(field,tickets);credit+=payout;lastPay=payout;played++;if(hit)hits++;history.unshift({round,winner:order[0].name,payout,bet:total()});history=history.slice(0,5);save();$('phase').textContent='RACE FINISHED';$('track-message').textContent=`${order[0].id+1} ${order[0].name} 優勝`;$('distance').textContent='FINISH';$('result').hidden=false;$('result').innerHTML=`<strong>${hit?'お見事、的中！':'次のレースで、もう一度。'}</strong><div class="podium">${order.slice(0,3).map((h,i)=>`<span>${i+1}着 <b style="color:${h.color}">${h.id+1}</b> ${h.name}</span>`).join('')}</div><div class="pay">PAY ${fmt(payout)} MEDALS</div>`;say(`${order[0].name}が1着！ ${order[1].name}が2着。${hit?`払戻は${fmt(payout)}枚です。`:'今回は惜しくも不的中。'}`);[523,659,784].forEach((n,i)=>setTimeout(()=>tone(n,.2),i*130));update()}
function frame(now){if(state!=='racing')return;elapsed=Math.max(elapsed,(now-startAt)/1000);const t=Math.max(0,elapsed-3);draw(t);const leader=[...field].sort((a,b)=>position(b,t)-position(a,t)||a.id-b.id)[0];const stage=elapsed<3?0:t<9?1:t<19?2:t<25?3:4;if(stage!==lastStage){lastStage=stage;const messages=['各馬ゲートイン。スタートまで、あと少し！','一斉にスタート！ 逃げ馬が前へ出ていきます。',`${leader.name}が先頭。後続もじわじわ差を詰めます。`,'さあ最後の直線！ 追い込み勢、ここから伸びる！','ゴール目前！ 最後まで目が離せません！'];say(messages[stage]);tone(stage?780:440,.15)}$('track-message').textContent=elapsed<3?`${Math.max(1,Math.ceil(3-elapsed))}`:t<25?'':`先頭 ${leader.id+1} ${leader.name}`;$('distance').textContent=elapsed<3?'GET READY':`残り ${Math.max(0,Math.ceil((1-position(leader,t))*1600/50)*50)} m`;if(sound&&elapsed-lastBeat>.25&&elapsed>3){lastBeat=elapsed;tone(110,.035)}if(t>=Math.max(...field.map(h=>h.time))+.6){finish();draw(t);return}requestAnimationFrame(frame)}
const canvas=$('track'),ctx=canvas.getContext('2d');
function horse(x,y,h,t){const gait=state==='racing'?Math.sin(t*19+h.id):0;ctx.save();ctx.translate(Math.round(x),Math.round(y));ctx.fillStyle='#101b14aa';ctx.fillRect(-23,24,62,6);ctx.fillStyle='#543829';ctx.fillRect(-19,0,39,18);ctx.fillRect(12,-12,12,23);ctx.fillRect(18,-19,23,12);ctx.fillRect(24,-25,6,8);ctx.fillStyle='#2c231c';ctx.fillRect(39,-15,6,8);ctx.fillRect(-28,0,12,5);ctx.fillStyle='#71513a';for(let i=0;i<4;i++){const offset=Math.round(gait*(i%2?6:-6));ctx.fillRect(-15+i*9+offset,15,5,13)}ctx.fillStyle=h.color;ctx.fillRect(-9,-5,22,14);ctx.fillRect(-6,-19,15,16);ctx.fillRect(5,-16,18,5);ctx.fillStyle='#e8d2a0';ctx.fillRect(-1,-27,9,9);ctx.fillStyle=h.color;ctx.fillRect(-4,-30,15,6);ctx.fillStyle='#fff';ctx.font='bold 12px monospace';ctx.fillText(h.id+1,-3,8);ctx.fillStyle='#121b13';ctx.fillRect(33,-17,3,3);ctx.restore()}
function draw(t){const w=1200,h=460;ctx.clearRect(0,0,w,h);ctx.fillStyle='#19341f';ctx.fillRect(0,0,w,h);ctx.fillStyle='#253f27';ctx.fillRect(0,62,w,357);for(let x=0;x<w;x+=16){ctx.fillStyle=x%32?'#29442a':'#264129';ctx.fillRect(x,63,8,352)}ctx.fillStyle='#101f17';ctx.fillRect(0,0,w,52);for(let x=0;x<w;x+=14){ctx.fillStyle=['#7e7955','#68755d','#a29a6b'][x/14%3|0];ctx.fillRect(x,15+(x%3)*8,6,7)}ctx.fillStyle='#68765a';ctx.fillRect(0,53,w,4);ctx.fillRect(0,415,w,4);for(let x=8;x<w;x+=65){ctx.fillStyle='#acb797';ctx.fillRect(x,53,3,14);ctx.fillRect(x,415,3,14)}for(let i=0;i<6;i++){ctx.fillStyle=i%2?'#314b2b44':'#172e1c44';ctx.fillRect(0,66+i*56,w,56);ctx.fillStyle='#829171';ctx.font='12px monospace';ctx.fillText(i+1,14,100+i*56)}const end=1110;for(let y=62;y<415;y+=12){ctx.fillStyle=(y/12|0)%2?'#decfa2':'#283325';ctx.fillRect(end,y,9,12);ctx.fillStyle=(y/12|0)%2?'#283325':'#decfa2';ctx.fillRect(end+9,y,9,12)}ctx.fillStyle='#d4b979';ctx.font='bold 13px monospace';ctx.fillText('GOAL',1090,444);ctx.fillStyle='#adac84';ctx.fillText('AMBER RACECOURSE / 1600m',34,444);field.forEach(h=>{const p=position(h,t);horse(68+p*(end-94),91+h.id*56,h,t)});ctx.fillStyle='#0000000b';for(let y=0;y<h;y+=4)ctx.fillRect(0,y,w,1)}
// Unfinished wagers are refunded on reload; completed payouts are saved once.
update();draw(0);save();
